774	/**
775	 * @brief 把箭头角度从当前显示值补间到目标角（0.1°）。
776	 * @param view       视图。
777	 * @param angle10    目标角，0..3599。
778	 * @param allow_anim false 时立即到位（首帧 / 隐藏后重新出现 / 正好掉头）。
779	 */
780	static void vmap_arrow_apply(vmap_view_t * view, int32_t angle10, bool allow_anim)
781	{
782	    int32_t cur;
783	    int32_t delta;
784	    lv_anim_t a;
785	
786	    if (view == NULL || view->arrow == NULL) {
787	        return;
788	    }
789	
790	    cur = view->disp_arrow_angle10;
791	    if (cur == INT32_MIN || !allow_anim) {
792	        lv_anim_delete(view, vmap_arrow_angle_exec);
793	        view->disp_arrow_angle10 = angle10;
794	        lv_img_set_angle(view->arrow, angle10);
795	        return;
796	    }
797	
798	    /* 最短弧：结果 -1800..1799（同模空间，cur 未归一化也成立）。 */
799	    delta = ((angle10 - cur + 3600 + 1800) % 3600) - 1800;
800	    if (abs(delta) < 30 || abs(delta) >= 1800) {
801	        lv_anim_delete(view, vmap_arrow_angle_exec);
802	        view->disp_arrow_angle10 = angle10;
803	        lv_img_set_angle(view->arrow, angle10);
804	        return;
805	    }
806	
807	    lv_anim_delete(view, vmap_arrow_angle_exec);
808	    lv_anim_init(&a);
809	    lv_anim_set_var(&a, view);
810	    lv_anim_set_values(&a, cur, cur + delta);
811	    lv_anim_set_duration(&a, 180);
812	    lv_anim_set_path_cb(&a, lv_anim_path_ease_out);
813	    lv_anim_set_exec_cb(&a, vmap_arrow_angle_exec);
814	    lv_anim_start(&a);
815	}
