817	static void tile_range(int32_t center_x, int32_t center_y, int32_t canvas_w,
818	    int32_t canvas_h, double scale, int32_t ring,
819	    int32_t * tx_min, int32_t * ty_min, int32_t * tx_max, int32_t * ty_max)
820	{
821	    const int32_t tile_size = 256;
822	    double half_w = (canvas_w / 2.0) / scale;
823	    double half_h = (canvas_h / 2.0) / scale;
824	    double pad = (double)ring * tile_size;
825	    double left = (double)center_x - half_w - pad;
826	    double top = (double)center_y - half_h - pad;
827	    double right = (double)center_x + half_w + pad;
828	    double bottom = (double)center_y + half_h + pad;
829	
830	    *tx_min = (int32_t)(left / tile_size) - (left < 0 ? 1 : 0);
831	    *ty_min = (int32_t)(top / tile_size) - (top < 0 ? 1 : 0);
832	    *tx_max = (int32_t)(right / tile_size);
833	    *ty_max = (int32_t)(bottom / tile_size);
834	}
