    cfg.title = "lvgl_sim";

    const char *scene_name = "demo";
    bool list_only = false;

    enum {
        OPT_UI_TOUR = 256,
        OPT_TOUR_FRAMES,
    };

    static const struct option long_opts[] = {
        { "scene",    required_argument, 0, 's' },
        { "size",     required_argument, 0, 'S' },
        { "scale",    required_argument, 0, 'k' },
        { "headless", no_argument,       0, 'H' },
        { "frames",   required_argument, 0, 'f' },
        { "shot",     required_argument, 0, 'o' },
        { "title",    required_argument, 0, 't' },
        { "ui-tour",  required_argument, 0, OPT_UI_TOUR },
        { "tour-frames", required_argument, 0, OPT_TOUR_FRAMES },
        { "list",     no_argument,       0, 'l' },
        { "help",     no_argument,       0, 'h' },
        { NULL, 0, NULL, 0 },
    };

    int c;
    while ((c = getopt_long(argc, argv, "s:S:k:Hf:o:t:lh", long_opts, NULL)) != -1) {
        switch (c) {
            case 's': scene_name = optarg; break;
            case 'S':
                if (sscanf(optarg, "%dx%d", &cfg.width, &cfg.height) != 2) {
                    fprintf(stderr, "bad --size\n");
                    return 2;
                }
                break;
            case 'k': cfg.scale = atoi(optarg); break;
            case 'H': cfg.headless = true; break;
            case 'f': cfg.frames = atoi(optarg); break;
            case 'o': cfg.shot = optarg; break;
            case 't': cfg.title = optarg; break;
            case OPT_UI_TOUR: cfg.ui_tour = optarg; break;
            case OPT_TOUR_FRAMES: cfg.tour_frames = atoi(optarg); break;
            case 'l': list_only = true; break;
            case 'h': usage(); return 0;
            default: usage(); return 2;
        }
    }

    if (list_only) {
        sim_scene_list();
        return 0;
    }

    const sim_scene_t *scene = sim_scene_find(scene_name);
    if (!scene) {
        fprintf(stderr, "unknown scene\n");
        sim_scene_list();
        return 2;
    }

    lv_init();
    lv_tick_set_cb(cfg.headless ? vtick_get : sim_tick_ms);

    if (!sim_display_init(&cfg)) {
        return 1;
    }
    sim_lvgl_bind();

    scene->create(lv_screen_active(), &cfg);
    printf("lvgl_sim: scene=%s %dx%d scale=%d %s\n", scene->name, cfg.width,
           cfg.height, cfg.scale, cfg.headless ? "headless" : "window");

    if (cfg.ui_tour != NULL && cfg.tour_frames <= 0) {
        cfg.tour_frames = 90;
    }

    if (cfg.headless) {
        /* 巡页模式下帧数由巡页状态机自己决定，这里只给一个死循环保护。
         * 只有 `ui` 场景会真正启用巡页（见 scenes.c）；其它场景带 --ui-tour
         * 也完全按原来的 --frames 跑。 */
        int frames = cfg.frames;

#ifdef SIM_WITH_UI
        const bool tour = sim_ui_tour_enabled();

        if (tour) {
            frames = 6000;
        }
#endif
        for (int i = 0; i < frames; i++) {
            s_vtick += 16;
            lv_timer_handler();
#ifdef SIM_WITH_UI
            if (tour && sim_ui_tour_done()) {
                break;
            }
            /* WP-FADE/R1 临时探针跑完即退出（未启用时恒为 false）。 */
            if (sim_ui_fade_probe_done()) {
                break;
            }
#endif
        }
        if (cfg.shot) {
            int w = 0;
            int h = 0;
            const uint16_t *fb = sim_display_shadow(&w, &h);

            if (!sim_png_write(cfg.shot, fb, w, h)) {
                fprintf(stderr, "failed to write png\n");
                sim_display_shutdown();
                return 1;
            }
            printf("shot -> %s (%dx%d)\n", cfg.shot, w, h);
        }
    } else {
        while (sim_display_pump()) {
            uint32_t idle = lv_timer_handler();

#ifdef SIM_WITH_UI
            if (sim_ui_tour_enabled() && sim_ui_tour_done()) {
                break;
            }
#endif
            if (idle < 1) {
                idle = 1;
            }
            if (idle > 16) {
                idle = 16;
            }
            usleep(idle * 1000);
        }
    }

    sim_display_shutdown();
    return 0;
}

1660	vmap_view_t * vmap_view_create(lv_obj_t * parent, int32_t view_w, int32_t view_h,
1661	    int32_t margin)
1662	{
1663	    vmap_view_t * view = (vmap_view_t *)calloc(1, sizeof(*view));
1664	    if (!view) {
1665	        return NULL;
1666	    }
1667	
1668	    vmap_perf_init_once();
1669	
1670	    view->view_w = view_w;
1671	    view->view_h = view_h;
1672	    view->margin = margin;
1673	    view->w = view_w + margin * 2;
1674	    view->h = view_h + margin * 2;
1675	    view->zoom = VMAP_DEFAULT_ZOOM;
1676	    view->scale = VMAP_DEFAULT_SCALE;
1677	    vmap_boot_lonlat(&view->lon, &view->lat);
1678	    view->render_lon = view->lon;
1679	    view->render_lat = view->lat;
1680	    view->follow_mode = true;
1681	    view->last_arrow_angle10 = INT32_MIN;
1682	    view->disp_arrow_angle10 = INT32_MIN;
1683	    view->last_pan_px = INT32_MIN;
1684	    view->last_pan_py = INT32_MIN;
1685	    view->paint_zoom = -1;
1686	
1687	    view->stride = lv_draw_buf_width_to_stride(view->w, LV_COLOR_FORMAT_RGB565);
1688	    /* ⚠ 画布**优先用专属 arena**（板级 MPU 只给它开 write-back，见
1689	     * `board_psram_layout.h` 的 `BOARD_PSRAM_CANVAS_ARENA_*`）：普通 PSRAM 池是
1690	     * write-through ⇒ 每次像素 store 都打到 PSRAM（~90 周期/次 ≈ 10 MB/s），
1691	     * 这是地图渲染慢的底层原因。arena 放不下就回退普通池（慢但能用）。 */
1692	    {
1693	        const size_t need = (size_t)view->stride * (size_t)view->h;
1694	        size_t arena_bytes = 0;
1695	        void * arena = board_psram_canvas_arena(&arena_bytes);
1696	
1697	        if (arena != NULL && need > 0 && need <= arena_bytes) {
1698	            view->cbuf = arena;
1699	            view->cbuf_arena = true;
1700	            /* 这里**不要**写 WB/WT：写入属性由板级 MPU 决定（见 board_psram_layout.h），
1701	             * MPU 侧没接上时 arena 仍是普通的 WT —— 写死"WB"会让人误判。 */
1702	            syslog(LOG_NOTICE,
1703	                   "[vmap] canvas arena %p +%u KiB (need %u KiB)",
1704	                   arena, (unsigned)(arena_bytes / 1024u),
1705	                   (unsigned)(need / 1024u));
1706	        } else {
1707	            view->cbuf = vmap_malloc(need);
1708	            syslog(LOG_WARNING,
1709	                   "[vmap] canvas fallback pool (need %u KiB, arena %u KiB)",
1710	                   (unsigned)(need / 1024u), (unsigned)(arena_bytes / 1024u));
1711	        }
1712	    }
1713	
1714	    if (!view->cbuf) {
1715	        free(view);
1716	        return NULL;
1717	    }
1718	
1719	    memset(view->cbuf, 0, (size_t)view->stride * (size_t)view->h);
1720	
1721	    /*
1722	     * 搬运后端自检（一次性，`[vblit]` 行）：拿真机画布几何测"同一块缓冲内
1723	     * 源/目的矩形重叠"的搬运能不能交给 EPIC。放在这里是因为画布尺寸刚定下、
1724	     * 还没有任何一帧在跑，而且自检缓冲用完立即释放。详见 vmap_blit.h。
1725	     */
1726	    vmap_blit_probe(view->w, view->h);
1727	
1728	    view->scratch = (vmap_point_t *)vmap_malloc(sizeof(vmap_point_t) * VMAP_SCRATCH_CAP);
1729	
1730	    /* 航向朝上用的屏幕对齐旋转缓冲 R（视口 + 四周余量）。分配不到就退回
1731	     * "LVGL 直接旋转画布"的老路径（慢但能用）。 */
1732	    view->r_margin = VMAP_ROT_MARGIN;
1733	    view->rw = view_w + 2 * view->r_margin;
1734	    view->rh = view_h + 2 * view->r_margin;
1735	    view->rstride = lv_draw_buf_width_to_stride(view->rw, LV_COLOR_FORMAT_RGB565);
1736	    view->rbuf = (uint16_t *)vmap_malloc((size_t)view->rstride * (size_t)view->rh);
1737	    if (view->rbuf != NULL) {
1738	        memset(view->rbuf, 0, (size_t)view->rstride * (size_t)view->rh);
1739	    }
1740	    /* 道路索引：只分配一次；失败只是回退逐 class 扫描，不影响可用性。 */
1741	    view->road_refs = (vmap_road_ref_t *)vmap_malloc(
1742	        sizeof(vmap_road_ref_t) * VMAP_ROAD_INDEX_CAP);
1743	    view->labels = (vmap_label_cand_t *)vmap_malloc(sizeof(vmap_label_cand_t) * VMAP_LABEL_CAP);
1744	    view->label_retained = (vmap_label_retained_t *)vmap_malloc(
1745	        sizeof(vmap_label_retained_t) * VMAP_LABEL_RETAIN_CAP);
1746	    view->cache = vmap_tile_cache_create();
1747	    if (!view->scratch || !view->labels || !view->label_retained || !view->cache) {
1748	        vmap_view_destroy(view);
1749	        return NULL;
1750	    }
1751	
1752	    if (view->road_refs) {
1753	        vmap_render_bind_road_index(view->road_refs, VMAP_ROAD_INDEX_CAP);
1754	    } else {
1755	        syslog(LOG_WARNING,
1756	            "[vmap] road index unavailable (%d), fallback to per-class scan",
1757	            VMAP_ROAD_INDEX_CAP);
1758	        vmap_render_bind_road_index(NULL, 0);
1759	    }
1760	
1761	    vmap_label_collector_init(&view->label_col, view->labels, VMAP_LABEL_CAP,
1762	        view->label_retained, VMAP_LABEL_RETAIN_CAP,
1763	        view->w, view->h, view->view_w, view->view_h, view->margin);
1764	
1765	    view->canvas = lv_canvas_create(parent);
1766	    lv_canvas_set_buffer(view->canvas, view->cbuf, view->w, view->h,
1767	        LV_COLOR_FORMAT_RGB565);
1768	    lv_obj_remove_style_all(view->canvas);
1769	    lv_obj_set_size(view->canvas, view->w, view->h);
1770	    lv_obj_set_pos(view->canvas, -margin, -margin);
1771	    /* 首帧 render_finish 前不要把 PSRAM 噪声送到 LCD。 */
1772	    lv_obj_add_flag(view->canvas, LV_OBJ_FLAG_HIDDEN);
1773	
1774	    /* 屏幕对齐的旋转缓冲对象（航向朝上时才显示）。 */
1775	    if (view->rbuf != NULL) {
1776	        view->rcanvas = lv_canvas_create(parent);
1777	        lv_canvas_set_buffer(view->rcanvas, view->rbuf, view->rw, view->rh,
1778	            LV_COLOR_FORMAT_RGB565);
1779	        lv_obj_remove_style_all(view->rcanvas);
1780	        lv_obj_set_size(view->rcanvas, view->rw, view->rh);
1781	        vmap_rot_place(view, 0, 0);
1782	        lv_obj_add_flag(view->rcanvas, LV_OBJ_FLAG_HIDDEN);
1783	    } else {
1784	        syslog(LOG_WARNING,
1785	            "[vmap] rotated buffer unavailable (%dx%d) → heading-up disabled",
1786	            (int)view->rw, (int)view->rh);
1787	    }
1788	
1789	    /* 航向朝上时的正立路名：独立文本对象（不烘进画布，否则会转成斜字）。 */
1790	    {
1791	        int32_t i;
1792	
1793	        view->rot_labels = true;
1794	        for (i = 0; i < VMAP_ROT_LABEL_MAX; i++) {
1795	            lv_obj_t * l = lv_label_create(parent);
1796	
1797	            lv_obj_remove_style_all(l);
1798	            lv_obj_remove_flag(l, LV_OBJ_FLAG_CLICKABLE);
1799	            lv_obj_remove_flag(l, LV_OBJ_FLAG_SCROLLABLE);
1800	            if (view->font != NULL) {
1801	                lv_obj_set_style_text_font(l, view->font, 0);
1802	            }
1803	            lv_obj_add_flag(l, LV_OBJ_FLAG_HIDDEN);
1804	            view->rot_label[i] = l;
1805	        }
1806	        view->rot_label_n = 0;
1807	    }
1808	
1809	    /* 帧率探针：挂在显示对象上，只挂一次（见 vmap_fps_probe_cb 的说明）。 */
1810	    if (!s_fps_hooked) {
1811	        lv_display_t * disp = lv_obj_get_display(view->canvas);
1812	
1813	        if (disp != NULL) {
1814	            lv_display_add_event_cb(disp, vmap_fps_probe_cb, LV_EVENT_ALL, NULL);
1815	            s_fps_hooked = true;
1816	        }
1817	    }
1818	
1819	    vmap_view_set_tile_dir(view, VMAP_TILE_DIR);
1820	    return view;
1821	}
