1823	/**
1824	 * @brief 销毁视图：释放画布与瓦片缓存。
1825	 */
1826	void vmap_view_destroy(vmap_view_t * view)
1827	{
1828	    int32_t i;
1829	
1830	    if (!view) {
1831	        return;
1832	    }
1833	
1834	    /* 动画回调以 view 为 var，必须先停，避免 view 释放后回调访问野指针。 */
1835	    lv_anim_delete(view, vmap_arrow_angle_exec);
1836	
1837	    view->track = NULL;
1838	
1839	    if (view->canvas) {
1840	        lv_obj_delete(view->canvas);
1841	        view->canvas = NULL;
1842	    }
1843	    if (view->arrow) {
1844	        lv_obj_delete(view->arrow);
1845	    }
1846	    if (view->rcanvas) {
1847	        lv_obj_delete(view->rcanvas);
1848	        view->rcanvas = NULL;
1849	    }
1850	    /* 标签是挂 parent 的独立对象，单独销毁视图不删会泄漏。 */
1851	    for (i = 0; i < VMAP_ROT_LABEL_MAX; i++) {
1852	        if (view->rot_label[i] != NULL) {
1853	            lv_obj_delete(view->rot_label[i]);
1854	            view->rot_label[i] = NULL;
1855	        }
1856	    }
1857	    view->rot_label_n = 0;
1858	    if (view->rbuf) {
1859	        vmap_free(view->rbuf);
1860	        view->rbuf = NULL;
1861	    }
1862	    if (view->cbuf && !view->cbuf_arena) {
1863	        vmap_free(view->cbuf);
1864	    }
1865	    if (view->scratch) {
1866	        vmap_free(view->scratch);
1867	    }
1868	    if (view->labels) {
1869	        vmap_free(view->labels);
1870	    }
1871	    if (view->label_retained) {
1872	        vmap_free(view->label_retained);
1873	    }
1874	    /* 先解绑再释放：渲染路径不能拿着即将释放的索引。只解自己的绑定——换主题
1875	     * 重建 shell 时可能"先建新视图再毁旧视图"，无条件解绑会把新视图的索引也
1876	     * 摘掉，之后静默退回逐 class 扫描（只是慢，不报错）。 */
1877	    if (vmap_render_road_index() == view->road_refs) {
1878	        vmap_render_bind_road_index(NULL, 0);
1879	    }
1880	    if (view->road_refs) {
1881	        vmap_free(view->road_refs);
1882	        view->road_refs = NULL;
1883	    }
1884	    vmap_tile_cache_destroy(view->cache);
1885	    free(view);
1886	}
