2202	/**
2203	 * @brief 按经纬度与航向摆箭头。
2204	 */
2205	void vmap_view_update_arrow(vmap_view_t * view, double lon, double lat, float course_deg)
2206	{
2207	    int32_t sx;
2208	    int32_t sy;
2209	    int32_t angle10;
2210	
2211	    if (!view || !view->arrow) {
2212	        return;
2213	    }
2214	
2215	    /* 航向朝上：地图已经转到"骑行方向朝上"，箭头就该固定指上；否则按航向转。 */
2216	    angle10 = view->heading_up ? 0
2217	        : ((int32_t)lroundf(course_deg * 10.0f) % 3600 + 3600) % 3600;
2218	    vmap_label_collector_set_focus(&view->label_col,
2219	        view->w / 2 + (int32_t)lround(view->pan_dx),
2220	        view->h / 2 + (int32_t)lround(view->pan_dy));
2221	
2222	    if (view->follow_mode) {
2223	        const bool hidden = lv_obj_has_flag(view->arrow, LV_OBJ_FLAG_HIDDEN);
2224	
2225	        if (angle10 == view->last_arrow_angle10 && !hidden
2226	            && view->disp_arrow_angle10 == angle10) {
2227	            return;
2228	        }
2229	        view->last_arrow_angle10 = angle10;
2230	        lv_obj_align(view->arrow, LV_ALIGN_CENTER, 0, view->y_bias);
2231	        vmap_arrow_apply(view, angle10, !hidden);
2232	        lv_obj_remove_flag(view->arrow, LV_OBJ_FLAG_HIDDEN);
2233	        lv_obj_move_foreground(view->arrow);
2234	        return;
2235	    }
2236	
2237	    if (!vmap_view_geo_to_viewport(view, lon, lat, &sx, &sy)) {
2238	        lv_anim_delete(view, vmap_arrow_angle_exec);
2239	        view->disp_arrow_angle10 = INT32_MIN;
2240	        lv_obj_add_flag(view->arrow, LV_OBJ_FLAG_HIDDEN);
2241	        return;
2242	    }
2243	
2244	    {
2245	        const bool hidden = lv_obj_has_flag(view->arrow, LV_OBJ_FLAG_HIDDEN);
2246	
2247	        if (!hidden && angle10 == view->last_arrow_angle10
2248	            && sx == lv_obj_get_x(view->arrow) + lv_obj_get_width(view->arrow) / 2
2249	            && sy == lv_obj_get_y(view->arrow) + lv_obj_get_height(view->arrow) / 2
2250	            && view->disp_arrow_angle10 == angle10) {
2251	            return;
2252	        }
2253	
2254	        view->last_arrow_angle10 = angle10;
2255	        lv_obj_set_pos(view->arrow,
2256	            sx - lv_obj_get_width(view->arrow) / 2,
2257	            sy - lv_obj_get_height(view->arrow) / 2 + view->y_bias);
2258	        vmap_arrow_apply(view, angle10, !hidden);
2259	        lv_obj_remove_flag(view->arrow, LV_OBJ_FLAG_HIDDEN);
2260	        lv_obj_move_foreground(view->arrow);
2261	    }
2262	}
