2337	    canvas->h = view->h;
2338	    canvas->stride = view->stride;
2339	    vmap_render_clip_reset(canvas);
2340	    if (!clip_dirty) {
2341	        return;
2342	    }
2343	    for (i = 0; i < view->pump_dirty_n; i++) {
2344	        vmap_render_clip_add(canvas,
2345	            view->pump_dirty_x1[i], view->pump_dirty_y1[i],
2346	            view->pump_dirty_x2[i], view->pump_dirty_y2[i]);
2347	    }
