2350	static void pump_dirty_add(vmap_view_t * view, int32_t x1, int32_t y1,
2351	    int32_t x2, int32_t y2)
2352	{
2353	    uint8_t i;
2354	
2355	    if (!view || x1 >= x2 || y1 >= y2) {
2356	        return;
2357	    }
2358	
2359	    if (x1 < 0) {
2360	        x1 = 0;
2361	    }
2362	    if (y1 < 0) {
2363	        y1 = 0;
2364	    }
2365	    if (x2 > view->w) {
2366	        x2 = view->w;
2367	    }
2368	    if (y2 > view->h) {
2369	        y2 = view->h;
2370	    }
2371	    if (x1 >= x2 || y1 >= y2 || view->pump_dirty_n >= VMAP_RENDER_DIRTY_MAX) {
2372	        return;
2373	    }
2374	
2375	    i = view->pump_dirty_n;
2376	    view->pump_dirty_x1[i] = x1;
2377	    view->pump_dirty_y1[i] = y1;
2378	    view->pump_dirty_x2[i] = x2;
2379	    view->pump_dirty_y2[i] = y2;
2380	    view->pump_dirty_n++;
2381	}
