2383	static void pump_dirty_from_scroll(vmap_view_t * view, int32_t sx, int32_t sy)
2384	{
2385	    const int32_t pad = (int32_t)VMAP_RENDER_DIRTY_PAD;
2386	
2387	    view->pump_dirty_n = 0;
2388	    if (sx > 0) {
2389	        pump_dirty_add(view, view->w - sx - pad, 0, view->w, view->h);
2390	    } else if (sx < 0) {
2391	        pump_dirty_add(view, 0, 0, -sx + pad, view->h);
2392	    }
2393	    if (sy > 0) {
2394	        pump_dirty_add(view, 0, view->h - sy - pad, view->w, view->h);
2395	    } else if (sy < 0) {
2396	        pump_dirty_add(view, 0, 0, view->w, -sy + pad);
2397	    }
2398	}
