2400	static bool pump_rects_overlap(int32_t ax1, int32_t ay1, int32_t ax2, int32_t ay2,
2401	    int32_t bx1, int32_t by1, int32_t bx2, int32_t by2)
2402	{
2403	    return ax1 < bx2 && ax2 > bx1 && ay1 < by2 && ay2 > by1;
2404	}
