2406	static bool pump_tile_dirty(const vmap_view_t * view, int32_t tx, int32_t ty)
2407	{
2408	    const int32_t tile_size = 256;
2409	    int32_t x1;
2410	    int32_t y1;
2411	    int32_t x2;
2412	    int32_t y2;
2413	    uint8_t i;
2414	
2415	    if (!view || view->pump_dirty_n == 0) {
2416	        return true;
2417	    }
2418	
2419	    x1 = (int32_t)lround((tx * tile_size - view->pump_cx) * view->scale
2420	        + view->w / 2.0);
2421	    y1 = (int32_t)lround((ty * tile_size - view->pump_cy) * view->scale
2422	        + view->h / 2.0);
2423	    x2 = (int32_t)lround(x1 + 256.0 * view->scale);
2424	    y2 = (int32_t)lround(y1 + 256.0 * view->scale);
2425	
2426	    for (i = 0; i < view->pump_dirty_n; i++) {
2427	        if (pump_rects_overlap(x1, y1, x2, y2,
2428	                view->pump_dirty_x1[i], view->pump_dirty_y1[i],
2429	                view->pump_dirty_x2[i], view->pump_dirty_y2[i])) {
2430	            return true;
2431	        }
2432	    }
2433	    return false;
2434	}
