2446	static void render_begin(vmap_view_t * view, bool reset_view, bool force_clear)
2447	{
2448	    vmap_canvas_t canvas;
2449	    const double origin_lon = reset_view ? view->lon : view->render_lon;
2450	    const double origin_lat = reset_view ? view->lat : view->render_lat;
2451	    int32_t sx;
2452	    int32_t sy;
2453	    bool scrolled = false;
2454	
2455	    /* 先置"帧在飞"再做任何 C 修改：期间的位置更新不能烘半成品。
2456	     * 两条路径（reset_view / keep-pan）都必须置位，否则泵不会推进。 */
2457	    view->pump_phase = 1;
2458	    view->pump_need_region = 1;

1120	static void vmap_view_apply_canvas_pos(vmap_view_t * view, double dx, double dy)
1121	{
1122	    lv_coord_t px;
1123	    lv_coord_t py;
1124	
1125	    if (!view || !view->canvas) {
1126	        return;
1127	    }
1128	
1129	    px = (lv_coord_t)lround(dx);
1130	    py = (lv_coord_t)lround(dy);
1131	
1132	    if (px == view->last_pan_px && py == view->last_pan_py) {
1133	        return;
1134	    }
1135	
1136	    /*
1137	     * Moving a canvas invalidates the complete visible map. Coalesce sub-pixel
1138	     * GNSS movement; the centered arrow still updates normally.
1139	     */
1140	    if (view->last_pan_px != INT32_MIN && view->last_pan_py != INT32_MIN
1141	        && abs((int)px - view->last_pan_px) < VMAP_PAN_MIN_STEP_PX
1142	        && abs((int)py - view->last_pan_py) < VMAP_PAN_MIN_STEP_PX) {
1143	        return;
1144	    }
1145	
1146	    view->pan_dx = (double)px;
1147	    view->pan_dy = (double)py;
1148	    view->last_pan_px = px;
1149	    view->last_pan_py = py;
1150	    view->map_rev++;
1151	    vmap_label_collector_set_focus(&view->label_col,
1152	        view->w / 2 + px, view->h / 2 + py);
1153	#if defined(CONFIG_MYVENDOR_BICYCLE_INVAL_PROBE) && CONFIG_MYVENDOR_BICYCLE_INVAL_PROBE
1154	    bicycle_inval_probe_tag("vmap_pan");
1155	#endif
1156	    /* lv_obj_set_pos already invalidates old + new areas; do not inval again. */
1157	    /* y_bias 只加在屏幕位置上：pan_dy 与投影原点都不动，于是偏置与跟车/rebase
1158	     * 的数学完全解耦（偏置变化既不触发重算，也不改变 rebase 时机）。 */
1159	    if (!view->heading_up) {
1160	        lv_obj_set_pos(view->canvas,
1161	            (lv_coord_t)(-view->margin - px),
1162	            (lv_coord_t)(-view->margin - py + view->y_bias));
1163	        return;
1164	    }
1165	
1166	    /*
1167	     * 航向朝上：不再让 LVGL 旋转画布（那样每次平移都要重跑一次任意角 transform，
1168	     * 实测 60 ms/次）。改成维护一块**屏幕对齐的旋转缓冲 R**：只有角度变化或
1169	     * 余量用完才重烘，平地跟车只移动 R 的对象（见 vmap_rot_track）。
1170	     */
1171	    vmap_rot_track(view);
1172	}
