1174	/**
1175	 * @brief 航向朝上：地图跟随骑行方向旋转（箭头恒指上）。
1176	 */
1177	void vmap_view_set_heading_up(vmap_view_t * view, bool enable)
1178	{
1179	    if (!view || view->heading_up == enable) {
1180	        return;
1181	    }
1182	
1183	    if (enable && (view->rcanvas == NULL || view->rbuf == NULL)) {
1184	        syslog(LOG_WARNING,
1185	            "[map] heading-up refused: rotated buffer unavailable\n");
1186	        return;
1187	    }
1188	
1189	    view->heading_up = enable;
1190	    view->heading_valid = false;
1191	    view->rot10 = 0;
1192	    view->want_rot10 = 0;
1193	    view->r_rot10 = -1;         /* 强制下一次 track 重烘 */
1194	    view->rot_pending = false;  /* 切换时会立刻重烘，旧的记账作废 */
1195	
1196	    if (enable) {
1197	        if (view->rcanvas) {
1198	            lv_obj_clear_flag(view->rcanvas, LV_OBJ_FLAG_HIDDEN);
1199	        }
1200	        if (view->canvas) {
1201	            lv_obj_add_flag(view->canvas, LV_OBJ_FLAG_HIDDEN);
1202	        }
1203	        if (view->render_rev != 0u) {
1204	            vmap_rot_why('S');
1205	            vmap_rot_full(view);    /* 画布已有内容才值得烘 */
1206	        }
1207	    } else {
1208	        if (view->rcanvas) {
1209	            lv_obj_add_flag(view->rcanvas, LV_OBJ_FLAG_HIDDEN);
1210	        }
1211	        if (view->canvas) {
1212	            lv_obj_clear_flag(view->canvas, LV_OBJ_FLAG_HIDDEN);
1213	        }
1214	        /* 正立路名只在航向朝上时用；退回正北后由烘焙路径接管。 */
1215	        {
1216	            int32_t i;
1217	
1218	            for (i = 0; i < VMAP_ROT_LABEL_MAX; i++) {
