/**
 * @file sim_display.c
 * @brief X11 窗口 + LVGL display/indev 绑定；headless 下只维护影子帧缓冲。
 *
 * 为什么不照搬 lv_port_linux：那个工程是 Kconfig/CMake 组件化的，源文件
 * 依赖它的 SDK 框架。这里只要"一块 RGB565 画布 + 鼠标键盘"，自己写
 * 200 行比拖一整套框架干净，而且窗口缩放、headless 截图都能自己控制。
 */

#define _POSIX_C_SOURCE 199309L

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#include <X11/Xlib.h>
#include <X11/Xutil.h>
#include <X11/keysym.h>

#include "sim.h"

static struct {
    Display *dpy;
    Window win;
    GC gc;
    XImage *img;
    Atom wm_delete;
    int w, h, scale;
    bool headless;
    bool quit;

    int mx, my;
    bool pressed;

    lv_group_t *group;
    lv_indev_t *indev_ptr;
    lv_indev_t *indev_key;

    uint32_t keys[32];
    int key_head, key_tail;
    uint32_t last_key;

    uint16_t *shadow;   /* 整帧影子：Expose 重画 + headless 截图都靠它 */
} s;

uint32_t sim_tick_ms(void)
{
    struct timespec ts;

    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (uint32_t)((uint64_t)ts.tv_sec * 1000u + (uint64_t)ts.tv_nsec / 1000000u);
}

static inline uint32_t rgb565_to_xrgb(uint16_t c)
{
    uint32_t r = (uint32_t)((c >> 11) & 0x1Fu);
    uint32_t g = (uint32_t)((c >> 5) & 0x3Fu);
    uint32_t b = (uint32_t)(c & 0x1Fu);

    r = (r << 3) | (r >> 2);
    g = (g << 2) | (g >> 4);
    b = (b << 3) | (b >> 2);
    return (r << 16) | (g << 8) | b;
}

/* 把影子缓冲的一块画到窗口（只画脏矩形，缩放用最近邻）。 */
static void blit_rect(int x0, int y0, int w, int h)
{
    if (s.headless || !s.dpy || !s.img) {
        return;
    }

    const int sc = s.scale;
    const int iw = s.w * sc;
    const bool fast = (s.img->bits_per_pixel == 32);

    for (int y = 0; y < h; y++) {
        const uint16_t *src = s.shadow + (size_t)(y0 + y) * (size_t)s.w + x0;
        for (int sy = 0; sy < sc; sy++) {
            int row = (y0 + y) * sc + sy;
            for (int x = 0; x < w; x++) {
                uint32_t rgb = rgb565_to_xrgb(src[x]);
                for (int sx = 0; sx < sc; sx++) {
                    int col = (x0 + x) * sc + sx;
                    if (fast) {
                        ((uint32_t *)s.img->data)[(size_t)row * (size_t)iw + col] = rgb;
                    } else {
                        XPutPixel(s.img, col, row, rgb);
                    }
                }
            }
        }
    }
    XPutImage(s.dpy, s.win, s.gc, s.img, x0 * sc, y0 * sc, x0 * sc, y0 * sc,
              (unsigned)w * (unsigned)sc, (unsigned)h * (unsigned)sc);
    XFlush(s.dpy);
}

/* ── LVGL flush ────────────────────────────────────────────────── */

static void flush_cb(lv_display_t *disp, const lv_area_t *area, uint8_t *px_map)
{
    const int w = (int)lv_area_get_width(area);
    const int h = (int)lv_area_get_height(area);
    const uint16_t *px = (const uint16_t *)px_map;

    for (int y = 0; y < h; y++) {
        memcpy(s.shadow + (size_t)(area->y1 + y) * (size_t)s.w + area->x1,
               px + (size_t)y * (size_t)w, (size_t)w * 2u);
    }
    blit_rect(area->x1, area->y1, w, h);
    lv_display_flush_ready(disp);
}
/* ── 输入 ──────────────────────────────────────────────────────── */

static void pointer_read(lv_indev_t *indev, lv_indev_data_t *data)
{
    (void)indev;
    data->point.x = (int32_t)s.mx;
    data->point.y = (int32_t)s.my;
    data->state = s.pressed ? LV_INDEV_STATE_PRESSED : LV_INDEV_STATE_RELEASED;
}

static void key_push(uint32_t key)
{
    int next = (s.key_tail + 1) % (int)(sizeof(s.keys) / sizeof(s.keys[0]));

    if (next == s.key_head) {
        return;
    }
    s.keys[s.key_tail] = key;
    s.key_tail = next;
}

static void keypad_read(lv_indev_t *indev, lv_indev_data_t *data)
{
    (void)indev;
    if (s.key_head != s.key_tail) {
        s.last_key = s.keys[s.key_head];
        s.key_head = (s.key_head + 1) % (int)(sizeof(s.keys) / sizeof(s.keys[0]));
        data->state = LV_INDEV_STATE_PRESSED;
    } else {
        data->state = LV_INDEV_STATE_RELEASED;
    }
    data->key = s.last_key;
}

static uint32_t xkey_to_lv(KeySym ks)
{
    switch (ks) {
        case XK_Left:  return LV_KEY_LEFT;
        case XK_Right: return LV_KEY_RIGHT;
        case XK_Up:    return LV_KEY_UP;
        case XK_Down:  return LV_KEY_DOWN;
        case XK_Return:
        case XK_KP_Enter: return LV_KEY_ENTER;
        case XK_Escape:   return LV_KEY_ESC;
        case XK_BackSpace:return LV_KEY_BACKSPACE;
        case XK_Tab:      return LV_KEY_NEXT;
        case XK_Home:     return LV_KEY_HOME;
        case XK_End:      return LV_KEY_END;
        default: return 0;
    }
}

lv_group_t *sim_input_group(void)
{
    if (!s.group) {
        s.group = lv_group_create();
        lv_group_set_default(s.group);
    }
    return s.group;
}

/* ── 事件循环 ──────────────────────────────────────────────────── */

bool sim_display_pump(void)
{
    if (s.headless || !s.dpy) {
        return !s.quit;
    }

    while (XPending(s.dpy)) {
        XEvent ev;

        XNextEvent(s.dpy, &ev);
        switch (ev.type) {
            case Expose:
                if (ev.xexpose.count == 0) {
                    blit_rect(0, 0, s.w, s.h);
                }
                break;
            case MotionNotify:
                s.mx = ev.xmotion.x / s.scale;
                s.my = ev.xmotion.y / s.scale;
                if (s.mx < 0) s.mx = 0;
                if (s.my < 0) s.my = 0;
                if (s.mx > s.w - 1) s.mx = s.w - 1;
                if (s.my > s.h - 1) s.my = s.h - 1;
                break;
            case ButtonPress:
                if (ev.xbutton.button == Button1) {
                    s.pressed = true;
                }
                break;
            case ButtonRelease:
                if (ev.xbutton.button == Button1) {
                    s.pressed = false;
                }
                break;
            case KeyPress: {
                KeySym ks = XLookupKeysym(&ev.xkey, 0);
                uint32_t key = xkey_to_lv(ks);

                if (key) {
                    key_push(key);
                }
                break;
            }
            case ClientMessage:
                if ((Atom)ev.xclient.data.l[0] == s.wm_delete) {
                    s.quit = true;
                }
                break;
            case DestroyNotify:
                s.quit = true;
                break;
            default:
                break;
        }
    }
    return !s.quit;
}

/* ── 初始化 ────────────────────────────────────────────────────── */

static bool shadow_alloc(void)
{
    s.shadow = calloc((size_t)s.w * (size_t)s.h, sizeof(uint16_t));
    if (!s.shadow) {
        fprintf(stderr, "sim: out of memory for shadow framebuffer\n");
        return false;
    }
    for (size_t i = 0; i < (size_t)s.w * (size_t)s.h; i++) {
        s.shadow[i] = 0xFFFF;
    }
    return true;
}

static bool window_open(const sim_cfg_t *cfg)
{
    const int scr = DefaultScreen(s.dpy);
    const int win_w = s.w * s.scale;
    const int win_h = s.h * s.scale;

    s.win = XCreateSimpleWindow(s.dpy, RootWindow(s.dpy, scr), 0, 0,
                                (unsigned)win_w, (unsigned)win_h, 0,
                                BlackPixel(s.dpy, scr), WhitePixel(s.dpy, scr));
    XStoreName(s.dpy, s.win, cfg->title ? cfg->title : "lvgl_sim");

    XSizeHints hints;
    memset(&hints, 0, sizeof(hints));
    hints.flags = PMinSize | PMaxSize;
    hints.min_width = hints.max_width = win_w;
    hints.min_height = hints.max_height = win_h;
    XSetWMNormalHints(s.dpy, s.win, &hints);

    s.wm_delete = XInternAtom(s.dpy, "WM_DELETE_WINDOW", False);
    XSetWMProtocols(s.dpy, s.win, &s.wm_delete, 1);

    XSelectInput(s.dpy, s.win,
                 ExposureMask | ButtonPressMask | ButtonReleaseMask |
                 PointerMotionMask | KeyPressMask | StructureNotifyMask);

    s.gc = XCreateGC(s.dpy, s.win, 0, NULL);

    s.img = XCreateImage(s.dpy, DefaultVisual(s.dpy, scr),
                         (unsigned)DefaultDepth(s.dpy, scr), ZPixmap, 0, NULL,
                         (unsigned)win_w, (unsigned)win_h, 32, 0);
    if (!s.img) {
        fprintf(stderr, "sim: XCreateImage failed\n");
        return false;
    }
    s.img->data = calloc((size_t)s.img->bytes_per_line, (size_t)win_h);
    if (!s.img->data) {
        fprintf(stderr, "sim: out of memory for XImage\n");
        return false;
    }

    XMapWindow(s.dpy, s.win);
    XFlush(s.dpy);

    if (s.img->bits_per_pixel != 32) {
        fprintf(stderr, "sim: warning: X server is %d bpp, using slow XPutPixel path\n",
                s.img->bits_per_pixel);
    }
    return true;
}

bool sim_display_init(const sim_cfg_t *cfg)
{
    s.w = cfg->width > 0 ? cfg->width : 240;
    s.h = cfg->height > 0 ? cfg->height : 400;
    s.scale = cfg->scale > 0 ? cfg->scale : 2;
    s.headless = cfg->headless;
    s.quit = false;

    if (!shadow_alloc()) {
        return false;
    }
    if (s.headless) {
        return true;
    }

    s.dpy = XOpenDisplay(NULL);
    if (!s.dpy) {
        fprintf(stderr, "sim: cannot open X display; use --headless --shot out.png\n");
        return false;
    }
    return window_open(cfg);
}

void sim_lvgl_bind(void)
{
    /* 两个 1/10 屏的局部缓冲：和设备的渲染模式一致，刷新时只送脏矩形 */
    const uint32_t stride = (uint32_t)s.w;
    const uint32_t lines = 40;
    const uint32_t bytes = stride * lines * 2u;
    void *buf1 = lv_malloc(bytes);
    void *buf2 = lv_malloc(bytes);

    lv_display_t *disp = lv_display_create(s.w, s.h);

    lv_display_set_flush_cb(disp, flush_cb);
    lv_display_set_buffers(disp, buf1, buf2, bytes, LV_DISPLAY_RENDER_MODE_PARTIAL);
    lv_display_set_default(disp);

    s.indev_ptr = lv_indev_create();
    lv_indev_set_type(s.indev_ptr, LV_INDEV_TYPE_POINTER);
    lv_indev_set_read_cb(s.indev_ptr, pointer_read);

    s.indev_key = lv_indev_create();
    lv_indev_set_type(s.indev_key, LV_INDEV_TYPE_KEYPAD);
    lv_indev_set_read_cb(s.indev_key, keypad_read);
    lv_indev_set_group(s.indev_key, sim_input_group());
}

const uint16_t *sim_display_shadow(int *w, int *h)
{
    if (w) *w = s.w;
    if (h) *h = s.h;
    return s.shadow;
}

void sim_display_shutdown(void)
{
    if (s.img) {
        /* XDestroyImage 会 free(data) */
        XDestroyImage(s.img);
        s.img = NULL;
    }
    if (s.gc && s.dpy) {
        XFreeGC(s.dpy, s.gc);
        s.gc = NULL;
    }
    if (s.win && s.dpy) {
        XDestroyWindow(s.dpy, s.win);
        s.win = 0;
    }
    if (s.dpy) {
        XCloseDisplay(s.dpy);
        s.dpy = NULL;
    }
    free(s.shadow);
    s.shadow = NULL;
}

/**
 * @file vmap_layer_probe.c
 * @brief 模拟器专用的 vmap 分层开关实现（见 vmap_layer_probe.h 的用法）。
 */

#include "vmap_layer_probe.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "vmap_format.h"

/** 与 `VMAP_STYLE_ROAD_CLASSES` 一致（这里不引 vmap_style.h，避免带进整套样式表）。 */
#define PROBE_CLS_MAX 8

/** 隐藏位图：bit(layer) 与 bit(8 + cls)。注意 bit0 是 WATER 层，不是 sentinel。 */
static unsigned s_mask;
/** "除背景外全隐藏"（SIM_VMAP_HIDE=all）。 */
static bool s_all;
/** bit(layer) = 该层被**显式保留**（SIM_VMAP_SHOW 模式）。 */
static unsigned s_keep;
static bool s_show_mode;
static bool s_inited;

static bool token_match(const char * tok, size_t len, const char * lit)
{
    return strlen(lit) == len && strncmp(tok, lit, len) == 0;
}

static void apply_token(const char * tok, size_t len, bool keep)
{
    struct {
        const char * name;
        int id;
    } layers[] = {
        { "water", VMAP_LAYER_WATER },
        { "forest", VMAP_LAYER_FOREST },
        { "waterway", VMAP_LAYER_WATERWAY },
        { "land", VMAP_LAYER_LAND },
        { "road", VMAP_LAYER_ROAD },
    };
    int cls_lo = 0;
    int cls_hi = 0;
    int i;

    if (len == 0) {
        return;
    }
    if (token_match(tok, len, "all")) {
        int l;

        for (l = 0; l < VMAP_LAYER_MAX; l++) {
            if (keep) {
                s_keep |= 1u << l;
            } else {
                s_mask |= 1u << l;
            }
        }
        if (!keep) {
            s_all = true;
        }
        return;
    }
    if (token_match(tok, len, "path")) {
        cls_lo = cls_hi = VMAP_ROAD_PATH;
    } else if (token_match(tok, len, "road46")) {
        cls_lo = VMAP_ROAD_TERTIARY;
        cls_hi = VMAP_ROAD_SERVICE;
    } else if (token_match(tok, len, "road1-3")) {
        cls_lo = VMAP_ROAD_MOTORWAY;
        cls_hi = VMAP_ROAD_SECONDARY;
    } else if (token_match(tok, len, "road")) {
        cls_lo = VMAP_ROAD_MOTORWAY;
        cls_hi = VMAP_ROAD_PATH;
    }

    if (cls_lo > 0) {
        for (i = cls_lo; i <= cls_hi; i++) {
            if (keep) {
                s_keep |= 1u << (8 + i);
            } else {
                s_mask |= 1u << (8 + i);
            }
        }
        /* 只关某个 class 时，ROAD 层本身仍要画，不能整层关。 */
        return;
    }

    for (i = 0; i < (int)(sizeof(layers) / sizeof(layers[0])); i++) {
        if (token_match(tok, len, layers[i].name)) {
            if (keep) {
                s_keep |= 1u << layers[i].id;
            } else {
                s_mask |= 1u << layers[i].id;
            }
            return;
        }
    }
}

static void scan_env(const char * env, const char * fallback, bool keep)
{
    const char * s = env;

    if (s == NULL || s[0] == '\0') {
        s = fallback;
    }
    while (s != NULL && s[0] != '\0') {
        const char * comma = strchr(s, ',');
        size_t len = comma ? (size_t)(comma - s) : strlen(s);

        while (len > 0 && (s[0] == ' ' || s[0] == '\t')) {
            s++;
            len--;
        }
        while (len > 0 && (s[len - 1] == ' ' || s[len - 1] == '\t')) {
            len--;
        }
        apply_token(s, len, keep);
        s = comma ? comma + 1 : NULL;
    }
}

static void probe_init(void)
{
    const char * hide;
    const char * show;

    if (s_inited) {
        return;
    }
    s_inited = true;

    hide = getenv("SIM_VMAP_HIDE");
    show = getenv("SIM_VMAP_SHOW");
    if (show != NULL && show[0] != '\0') {
        s_show_mode = true;
        scan_env(show, NULL, true);
    } else {
        scan_env(hide, NULL, false);
    }
    if (s_all || s_mask != 0u || s_keep != 0u) {
        fprintf(stderr, "sim_vmap: layer probe on (all=%d hide=0x%x keep=0x%x)\n",
            (int)s_all, s_mask, s_keep);
    }
}

bool sim_vmap_layer_on(int layer)
{
    probe_init();

    if (!s_all && s_mask == 0u && s_keep == 0u) {
        return true;
    }
    if (s_all) {
        return false;
    }
    if (layer < 0 || layer >= VMAP_LAYER_MAX) {
        return true;
    }
    if (s_show_mode) {
        return (s_keep & (1u << layer)) != 0u;
    }
    return (s_mask & (1u << layer)) == 0u;
}

bool sim_vmap_cls_on(int cls)
{
    probe_init();

    if (!s_all && s_mask == 0u && s_keep == 0u) {
        return true;
    }
    if (cls < 1 || cls >= PROBE_CLS_MAX) {
        return true;
    }
    if (s_all) {
        return false;
    }
    if (s_show_mode) {
        const bool keep_any_cls = (s_keep & 0x7f00u) != 0u;

        return !keep_any_cls || ((s_keep & (1u << (8 + cls))) != 0u);
    }
    return (s_mask & (1u << (8 + cls))) == 0u;
}

bool sim_vmap_any_hidden(void)
{
    probe_init();

    return s_all || s_mask != 0u || s_keep != 0u;
}

static int env_int(const char * name)
{
    const char * e = getenv(name);

    return (e != NULL && e[0] != '\0') ? atoi(e) : 0;
}

bool sim_vmap_path_solid(void)
{
    return env_int("SIM_VMAP_PATH_SOLID") > 0;
}

int sim_vmap_path_min_px(void)
{
    return env_int("SIM_VMAP_PATH_MIN_PX");
}

int sim_vmap_path_short_solid_px(void)
{
    return env_int("SIM_VMAP_PATH_SHORT_SOLID");
}
/**
 * @file vmap_layer_probe.h
 * @brief 模拟器专用的 vmap 分层开关（**只用于出对证据图，默认全开**）。
 *
 * 板端没有这个开关，也不会读到它：`ui_port/CMakeLists.txt` 只对**构建期副本**
 * `build/ui_port/vendor_patched/vmap_render.c` 注入几行 `if (!sim_vmap_*_on(...))`
 * 判据，vendor 源码一行不动。环境变量没设时所有函数返回 true，像素与不带本
 * 探针时逐字节相同（可回归验证：`SIM_VMAP_HIDE=` 空运行时 compare = 0）。
 *
 * 用法：
 *   SIM_VMAP_HIDE=path            隐藏 cls7（棕色虚线步道）
 *   SIM_VMAP_HIDE=road46          隐藏 cls4..6（支路/服务路，带壳）
 *   SIM_VMAP_HIDE=road            隐藏所有道路（cls1..7）
 *   SIM_VMAP_HIDE=land,forest     隐藏用地/林地（可任意组合，逗号分隔）
 *   SIM_VMAP_HIDE=water,waterway  隐藏水面/水系线
 *   SIM_VMAP_HIDE=all             除背景外全隐藏
 *   SIM_VMAP_SHOW=path            只留 cls7（等价于 hide 了其它全部）
 *
 * 环境变量取一次后缓存，运行中改不生效（headless 单帧出图足够）。
 */

#ifndef SIM_VMAP_LAYER_PROBE_H
#define SIM_VMAP_LAYER_PROBE_H

#include <stdbool.h>

#ifdef __cplusplus
extern "C" {
#endif

/** @brief 该图层是否绘制（参数用 VMAP_LAYER_*，5 = LAND）。 */
bool sim_vmap_layer_on(int layer);

/** @brief 该道路等级（1..7）是否绘制。 */
bool sim_vmap_cls_on(int cls);

/** @brief 是否有任何层被隐藏（假时渲染走原路径，零额外分支开销可忽略）。 */
bool sim_vmap_any_hidden(void);

/* ── cls7（path）画法的 A/B 试验开关（默认关 = 现行行为） ────────────────
 * 只为了在模拟器里量"修法长什么样"，不是板端逻辑：
 *   SIM_VMAP_PATH_SOLID=1     cls7 不走虚线，画实线
 *   SIM_VMAP_PATH_MIN_PX=N    屏幕长度 < N 设备像素的 cls7 整条不画
 *   SIM_VMAP_PATH_SHORT_SOLID=N  屏幕长度 < N 的 cls7 画实线，≥N 仍画虚线
 * 三个都不设时函数返回 0/false，渲染结果与不带探针时逐像素相同。
 */
bool sim_vmap_path_solid(void);
int sim_vmap_path_min_px(void);
int sim_vmap_path_short_solid_px(void);

#ifdef __cplusplus
}
#endif

#endif /* SIM_VMAP_LAYER_PROBE_H */

