993	        && (uint32_t)(lv_tick_get() - view->last_fail_ms) < VMAP_ROT_BAKE_MIN_MS) {
994	        return false;
995	    }
996	
997	    /* 骑手在画布里的位置 = 画布中心 + 跟车 pan。 */
998	    pivot_x = view->margin + view->view_w / 2 + (int32_t)lround(view->pan_dx);
999	    pivot_y = view->margin + view->view_h / 2 + (int32_t)lround(view->pan_dy);
1000	    if (pivot_x < 0 || pivot_y < 0 || pivot_x >= view->w || pivot_y >= view->h) {
1001	        pivot_x = view->w / 2;
1002	        pivot_y = view->h / 2;
1003	    }
