1005	    if (!myvendor_epic_rotate(view->cbuf, view->stride, view->w, view->h,
1006	            view->rbuf, view->rstride, view->rw, view->rh, view->rot10,
1007	            pivot_x, pivot_y, view->rw / 2, view->rh / 2)) {
