1022	        view->rot_fail_valid = true;
1023	        view->rot_broken = true;
1024	        view->last_fail_ms = lv_tick_get();
1025	        return false;
1026	    }
1027	
1028	    view->r_pan_x = view->pan_dx;
1029	    view->r_pan_y = view->pan_dy;
1030	    view->r_rot10 = view->rot10;
1031	    view->rot_pending = false;
1032	    view->rot_fail_valid = false;
1033	    view->rot_broken = false;
