1042	/**
1043	 * @brief 把"帧外增量还没进 R"的记账补烘掉（限频窗口内先留着）。
1044	 *
1045	 * @details 由 200 ms 的航向拍调用（`vmap_view_set_heading`），所以即使某次增量
1046	 *          之后再没有任何失效，内容也会在窗口到期后的下一拍上屏；不会永远停在旧版本。
1047	 */
1048	static void vmap_rot_service(vmap_view_t * view)
1049	{
