1051	
1052	    if (view == NULL || !view->heading_up) {
1053	        return;
1054	    }
1055	    angle = (view->want_rot10 != view->rot10);
1056	    if (!angle && !view->rot_pending) {
1057	        return;
1058	    }
1059	    if (view->pump_phase != 0u || view->rcanvas == NULL
1060	        || view->render_rev == 0u
1061	        || lv_obj_has_flag(view->rcanvas, LV_OBJ_FLAG_HIDDEN)) {
1062	        return;                 /* 帧在飞（帧末会烘）或还没显示/还没有首帧 */
1063	    }
1064	    if (view->last_bake_ms != 0u
1065	        && lv_tick_elaps(view->last_bake_ms) < VMAP_ROT_BAKE_MIN_MS) {
1066	        return;                 /* 限频窗口未到：下一拍再来 */
1067	    }
1068	    /*
1069	     * 待应用角度与"帧外增量"合并到**同一次**重烘：否则先用旧角度烘一次增量会刷新
1070	     * `last_bake_ms`，把角度请求一直挡在窗口外（持续记录时地图永远保持旧朝向）。
1071	     * 角度**成功烘完才提交**：EPIC 旋转失败时保留 want_rot10，下一拍自动重试，
1072	     * 不会把请求悄悄丢掉（否则静止时再没有别的东西会触发重烘）。
1073	     */
1074	    {
1075	        const int32_t prev_rot10 = view->rot10;
1076	
1077	        /* 探针放在限频检查**之后**：这里才是真的要烘一次（之前的位置会把被窗口挡掉
1078	         * 的重试也记成一次触发）。 */
1079	        vmap_rot_why(angle ? 'A' : 'N');
1080	        view->rot10 = view->want_rot10;
1081	        if (!vmap_rot_full(view)) {
