1094	    const double c = cos(th);
1095	    const double s = sin(th);
1096	    const double dpx = view->pan_dx - view->r_pan_x;
1097	    const double dpy = view->pan_dy - view->r_pan_y;
1098	    const int32_t sx = (int32_t)lround(-(c * dpx - s * dpy));
1099	    const int32_t sy = (int32_t)lround(-(s * dpx + c * dpy));
