1105	     */
1106	    if (view->rot_broken) {
1107	        return;
1108	    }
1109	
1110	    if (view->rot10 != view->r_rot10
1111	        || abs((int)sx) > lim || abs((int)sy) > lim) {
1112	        vmap_rot_why('T');
1113	        vmap_rot_full(view);    /* 角度变了、或余量用完了；失败记账在它内部 */
1114	        return;
1115	    }
1116	
1117	    vmap_rot_place(view, sx, sy);
1118	}
