static void vmap_live_tick(lv_timer_t *t) {
    (void)t;
    if (s.view == NULL) return;

    /* scripted pan: 等首帧完成 */
    if (s.pan_pending && !vmap_view_render_busy(s.view) && vmap_view_render_revision(s.view) > 0) {
        apply scripted pan
    }

    /* wheel */
    int w = sim_display_take_wheel();
    if (w) zoom step.

    /* raw keys */
    int k;
    while ((k = sim_display_take_raw_key()) != 0) handle.

    if (vmap_view_render_busy(s.view)) vmap_view_render_pump(s.view, 8);
    update_hud();
}
