 *   - 运行时中心图标              `--vmap-icon dev|alt|none`（set_center_icon）
 *   - 运行时中心点                `--vmap-center LON,LAT`（center_on）
 *   - 拖动                       鼠标拖动 / `--vmap-pan DX,DY`（pan_begin/px/end）
 *   - 连续缩放                   滚轮 / `+` `-` / `--vmap-scale S`（set_scale）
 *
 * HUD 显示 lon/lat/scale/viewport/中心图标，便于截图直接读参数。
 */

#include <math.h>
#include <stdio.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>

#include "sim.h"

#include "NaviArrow.h"
#include "vmap_config.h"
#include "vmap_tile_system.h"
#include "vmap_view.h"

#define LIVE_SCREEN_BG   0x121417
#define LIVE_MAP_BG      0xEFE9DA
#define LIVE_FRAME_COLOR 0xFF4D4D
#define LIVE_WHEEL_STEP  1.15

typedef struct {
    lv_obj_t * scr;
    lv_obj_t * holder;
    lv_obj_t * overlay;
    lv_obj_t * hud;
    lv_obj_t * hud_label;
    vmap_view_t * view;
    lv_timer_t * timer;

    int vw;
    int vh;

    /* 启动参数（也是 r 键的复位目标） */
    double boot_lon;
    double boot_lat;
    double boot_scale;
    int boot_icon;

    double lon;
    double lat;
    double scale;
    int zoom;
    int icon;

    bool follow;

    bool pan_pending;    /**< 脚本化平移还没执行 */
    bool pan_applied;
    int pan_dx;
    int pan_dy;

    double pending_scale; /**< 泵忙时先记账的缩放（0 = 无） */

    /* `alt` 中心图标：运行时生成的 ARGB8888 准星（不依赖板端资源） */
    lv_image_dsc_t alt_dsc;
    uint8_t * alt_px;
} live_t;

static live_t s;

/* ─────────────────────────────────────────────────────────────────────────
 * 中心图标
 * ──────────────────────────────────────────────────────────────────────── */

static const char * icon_name(int icon)
{
    switch (icon) {
        case SIM_VMAP_ICON_ALT:  return "crosshair";
        case SIM_VMAP_ICON_NONE: return "none";
        default:                 return "dev-arrow";
    }
}

/**
 * @brief 运行时画一枚 36x36 的蓝色准星（ARGB8888）。
 *
 * 板端两枚箭头都是编译进 flash 的位图；模拟器要验证"可换图"，再带一张
 * 完全不同的图最直观，也避免依赖 PNG 解码器。
 */
static void alt_icon_build(void)
{
    enum { W = 36, H = 36 };
    const uint32_t blue = 0x001D6FD0u;

    s.alt_px = (uint8_t *)lv_malloc((size_t)W * H * 4u);
    if (s.alt_px == NULL) {
        return;
    }
    memset(s.alt_px, 0, (size_t)W * H * 4u);

    for (int y = 0; y < H; y++) {
        for (int x = 0; x < W; x++) {
            const double dx = (double)x - (W - 1) / 2.0;
            const double dy = (double)y - (H - 1) / 2.0;
            const double r = sqrt(dx * dx + dy * dy);
            uint32_t argb = 0u;

            if (r >= 14.5 && r <= 16.5) {
                argb = 0xFF1D6FD0u;                  /* 外圈：蓝 */
            } else if (r >= 12.0 && r <= 13.0) {
                argb = 0xFFFFFFFFu;                  /* 内圈：白 */
            } else if (r <= 3.2) {
                argb = 0xFF1D6FD0u;                  /* 中心点 */
            } else if ((fabs(dx) <= 1.0 && fabs(dy) >= 9.0 && fabs(dy) <= 16.5)
                || (fabs(dy) <= 1.0 && fabs(dx) >= 9.0 && fabs(dx) <= 16.5)) {
                argb = 0xFF1D6FD0u;                  /* 四个方向的刻度 */
            }

            if (argb != 0u) {
                uint8_t * p = s.alt_px + ((size_t)y * W + (size_t)x) * 4u;

                p[0] = (uint8_t)(argb & 0xFFu);        /* B */
                p[1] = (uint8_t)((argb >> 8) & 0xFFu); /* G */
                p[2] = (uint8_t)((argb >> 16) & 0xFFu);/* R */
                p[3] = (uint8_t)((argb >> 24) & 0xFFu);/* A */
            }
        }
    }
    (void)blue;

    memset(&s.alt_dsc, 0, sizeof(s.alt_dsc));
    s.alt_dsc.header.magic = LV_IMAGE_HEADER_MAGIC;
    s.alt_dsc.header.cf = LV_COLOR_FORMAT_ARGB8888;
    s.alt_dsc.header.w = W;
    s.alt_dsc.header.h = H;
    s.alt_dsc.header.stride = W * 4;
    s.alt_dsc.data_size = W * H * 4u;
    s.alt_dsc.data = s.alt_px;
}

static const void * icon_src(int icon)
{
    switch (icon) {
        case SIM_VMAP_ICON_NONE:
            return NULL;
        case SIM_VMAP_ICON_ALT:
            return s.alt_px != NULL ? (const void *)&s.alt_dsc : NULL;
        default:
            return (const void *)navi_arrow_get(NAVI_ARROW_LIGHT);
    }
}

static void icon_apply(void)
{
    vmap_view_set_center_icon(s.view, icon_src(s.icon));
    /* follow 关闭时图标要回到"它的地面位置"，不能停在旧中心。 */
    vmap_view_update_arrow(s.view, s.lon, s.lat, 0.0f);
}

/* ─────────────────────────────────────────────────────────────────────────
 * HUD
 * ──────────────────────────────────────────────────────────────────────── */

static void hud_update(void)
{
    char line1[64];
    char line2[64];
    char line3[64];
    char line4[64];
    char text[256];
    double lon = 0.0;
    double lat = 0.0;
    int32_t pan_x = 0;
    int32_t pan_y = 0;

    if (s.view == NULL) {
        return;
    }

    vmap_view_get_center(s.view, &lon, &lat);
    vmap_view_get_pan(s.view, &pan_x, &pan_y);

    snprintf(line1, sizeof(line1), "vmap real z%d  vp %dx%d",
        s.zoom, s.vw, s.vh);
    snprintf(line2, sizeof(line2), "lon %.6f lat %.6f", lon, lat);
    snprintf(line3, sizeof(line3), "scale %.2f  icon %s", s.scale, icon_name(s.icon));
    snprintf(line4, sizeof(line4), "follow %s  pan %+d,%+d  rev %u",
        s.follow ? "on " : "off", (int)pan_x, (int)pan_y,
        (unsigned)vmap_view_render_revision(s.view));

    snprintf(text, sizeof(text), "%s\n%s\n%s\n%s", line1, line2, line3, line4);
    lv_label_set_text(s.hud_label, text);
}

/* ─────────────────────────────────────────────────────────────────────────
 * 交互
 * ──────────────────────────────────────────────────────────────────────── */

static void set_scale_deferred(double scale)
{
    if (scale < 0.5) {
        scale = 0.5;
    } else if (scale > 4.0) {
        scale = 4.0;
    }
    if (fabs(scale - s.scale) < 1e-6) {
        return;
    }
    s.scale = scale;
    if (s.view == NULL) {
        return;
    }
    /* 帧在飞时不要改 scale：paint_scale 会在 render_finish 里记成新值，
     * 于是这一帧被误当成"已按新倍率画过"。先记账，等帧结束再应用。 */
    if (vmap_view_render_busy(s.view)) {
        s.pending_scale = scale;
        return;
    }
    s.pending_scale = 0.0;
    vmap_view_set_scale(s.view, scale);
    vmap_view_render(s.view);
}

static void reset_view(void)
{
    s.lon = s.boot_lon;
    s.lat = s.boot_lat;
    s.scale = s.boot_scale;
    s.icon = s.boot_icon;
    s.follow = true;
    s.pending_scale = 0.0;

    vmap_view_set_scale(s.view, s.boot_scale);
    vmap_view_set_follow_mode(s.view, true);
    vmap_view_center_on(s.view, s.boot_lon, s.boot_lat);
    icon_apply();
    vmap_view_update_arrow(s.view, s.boot_lon, s.boot_lat, 0.0f);
    printf("[vmap] reset lon=%.6f lat=%.6f scale=%.2f icon=%s\n",
        s.boot_lon, s.boot_lat, s.boot_scale, icon_name(s.icon));
}

/**
 * @brief 脚本化平移：首帧渲染完成后执行一次，并打印同一地物的像素位移。
 */
static void pan_script_run(void)
{
    int32_t x0 = 0;
    int32_t y0 = 0;
    int32_t x1 = 0;
    int32_t y1 = 0;
    double lon2 = 0.0;
    double lat2 = 0.0;

    s.pan_pending = false;
    s.pan_applied = true;

    /* 参考地物 = 初始中心点。拖动前后各投一次屏幕坐标。 */
    (void)vmap_view_geo_to_viewport_raw(s.view, s.lon, s.lat, &x0, &y0);

    vmap_view_pan_begin(s.view);
    s.follow = false;
    vmap_view_pan_px(s.view, s.pan_dx, s.pan_dy);
    vmap_view_pan_end(s.view);

    (void)vmap_view_geo_to_viewport_raw(s.view, s.lon, s.lat, &x1, &y1);
    vmap_view_update_arrow(s.view, s.lon, s.lat, 0.0f);
    vmap_view_get_center(s.view, &lon2, &lat2);

    printf("[vmap-pan] requested=(%+d,%+d) ref=(%.6f,%.6f) before=(%d,%d) "
           "after=(%d,%d) delta=(%+d,%+d) new_center=(%.6f,%.6f) follow=%d\n",
        s.pan_dx, s.pan_dy, s.lon, s.lat, (int)x0, (int)y0, (int)x1, (int)y1,
        (int)(x1 - x0), (int)(y1 - y0), lon2, lat2,
        (int)vmap_view_is_following(s.view));
}

static void drag_cb(lv_event_t * e)
{
    const lv_event_code_t code = lv_event_get_code(e);
    lv_indev_t * indev;

    if (s.view == NULL) {
        return;
    }

    switch (code) {
        case LV_EVENT_PRESSED:
            vmap_view_pan_begin(s.view);
            s.follow = false;
            break;
        case LV_EVENT_PRESSING: {
            lv_point_t v;

            indev = lv_indev_active();
            if (indev == NULL) {
                break;
            }
            lv_indev_get_vect(indev, &v);
            if (v.x != 0 || v.y != 0) {
                vmap_view_pan_px(s.view, v.x, v.y);
                /* follow 已打断：图标按经纬度跟着地面走。 */
                vmap_view_update_arrow(s.view, s.lon, s.lat, 0.0f);
            }
            break;
        }
        case LV_EVENT_RELEASED:
        case LV_EVENT_PRESS_LOST:
            vmap_view_pan_end(s.view);
            vmap_view_update_arrow(s.view, s.lon, s.lat, 0.0f);
            break;
        default:
            break;
    }
}

static void key_handle(int key)
{
    switch (key) {
        case '1': s.icon = SIM_VMAP_ICON_DEV;  icon_apply(); break;
        case '2': s.icon = SIM_VMAP_ICON_ALT;  icon_apply(); break;
        case '3': s.icon = SIM_VMAP_ICON_NONE; icon_apply(); break;
        case 'i': s.icon = (s.icon + 1) % 3;   icon_apply(); break;
        case '+': set_scale_deferred(s.scale * LIVE_WHEEL_STEP); break;
        case '-': set_scale_deferred(s.scale / LIVE_WHEEL_STEP); break;
        case 'f':
            if (s.follow) {
                vmap_view_pan_begin(s.view);
                s.follow = false;
                vmap_view_update_arrow(s.view, s.lon, s.lat, 0.0f);
            } else {
                vmap_view_set_follow_mode(s.view, true);
                s.follow = true;
                vmap_view_update_arrow(s.view, s.lon, s.lat, 0.0f);
            }
            printf("[vmap] follow=%d\n", (int)s.follow);
            break;
        case 'r': reset_view(); break;
        default: break;
    }
}

/* ─────────────────────────────────────────────────────────────────────────
 * 每拍工作（沿用页面的 10 ms pump 节奏，不引入新的高频定时器）
 * ──────────────────────────────────────────────────────────────────────── */

static void live_tick(lv_timer_t * t)
{
    (void)t;

    if (s.view == NULL) {
        return;
    }

    /* 脚本化平移：等首帧（render_revision > 0）完成后做一次。 */
    if (s.pan_pending && !vmap_view_render_busy(s.view)
        && vmap_view_render_revision(s.view) > 0u) {
        pan_script_run();
    }

    {
        const int wheel = sim_display_take_wheel();

        if (wheel != 0) {
            set_scale_deferred(s.scale * pow(LIVE_WHEEL_STEP, (double)wheel));
        }
    }

    for (int k = sim_display_take_raw_key(); k != 0; k = sim_display_take_raw_key()) {
        key_handle(k);
    }

    if (vmap_view_render_busy(s.view)) {
        vmap_view_render_pump(s.view, 8);
    } else if (s.pending_scale > 0.0) {
        const double sc = s.pending_scale;

        s.pending_scale = 0.0;
        s.scale = sc;
        vmap_view_set_scale(s.view, sc);
        vmap_view_render(s.view);
    }

    s.follow = vmap_view_is_following(s.view);
    hud_update();
}

/* ─────────────────────────────────────────────────────────────────────────
 * 场景入口
 * ──────────────────────────────────────────────────────────────────────── */

static void map_path_hint(void)
{
    struct stat st;

    if (lstat("/tmp/vmap", &st) == 0) {
        return;
    }
    /* 与 ui_boot.c 的 ensure_short_map_path() 同一做法：板端目录名存进
     * 64 字节缓冲，PC 上的长路径会被截断。 */
    if (symlink(SIM_VMAP_REAL_DIR, "/tmp/vmap") != 0) {
        fprintf(stderr, "vmap: 建不了 /tmp/vmap -> %s（地图会空白）\n",
            SIM_VMAP_REAL_DIR);
    }
}

void scene_vmap_live_create(lv_obj_t * scr, const sim_cfg_t * cfg)
{
    const int sw = cfg->width;
    const int sh = cfg->height;
    const int hud_h = 4 * 16 + 10;
    int hud_y;
    int32_t cx = 0;
    int32_t cy = 0;
    int zoom;

    memset(&s, 0, sizeof(s));
    s.scr = scr;

    map_path_hint();

    /* ── 尺寸与中心：参数优先，缺省用屏幕/板端开机中心 ─────────────── */
    s.vw = cfg->vmap_w > 0 ? cfg->vmap_w : sw;
    s.vh = cfg->vmap_h > 0 ? cfg->vmap_h : sh;
    if (s.vw > sw || s.vh > sh) {
        fprintf(stderr, "vmap: viewport %dx%d 超出屏幕 %dx%d（用 --size 放大屏幕）\n",
            s.vw, s.vh, sw, sh);
        if (s.vw > sw) {
            s.vw = sw;
        }
        if (s.vh > sh) {
            s.vh = sh;
        }
    }
    zoom = cfg->vmap_zoom > 0 ? cfg->vmap_zoom : VMAP_DEFAULT_ZOOM;
    s.zoom = zoom;
    s.scale = cfg->vmap_scale > 0.0 ? cfg->vmap_scale : VMAP_DEFAULT_SCALE;
    s.icon = cfg->vmap_icon;

    if (isfinite(cfg->vmap_lon) && isfinite(cfg->vmap_lat)) {
        s.lon = cfg->vmap_lon;
        s.lat = cfg->vmap_lat;
    } else {
        vmap_boot_lonlat(&s.lon, &s.lat);
    }
    s.boot_lon = s.lon;
    s.boot_lat = s.lat;
    s.boot_scale = s.scale;
    s.boot_icon = s.icon;
    s.follow = true;

    s.pan_pending = cfg->vmap_pan_set;
    s.pan_dx = cfg->vmap_pan_x;
    s.pan_dy = cfg->vmap_pan_y;

    /* ── 屏幕 / 视口容器 ──────────────────────────────────────────── */
    lv_obj_set_style_bg_color(scr, lv_color_hex(LIVE_SCREEN_BG), 0);
    lv_obj_set_style_bg_opa(scr, LV_OPA_COVER, 0);
    lv_obj_remove_flag(scr, LV_OBJ_FLAG_SCROLLABLE);

    s.holder = lv_obj_create(scr);
    lv_obj_remove_style_all(s.holder);
    lv_obj_set_size(s.holder, s.vw, s.vh);
    lv_obj_set_pos(s.holder, 0, 0);
    lv_obj_set_style_bg_color(s.holder, lv_color_hex(LIVE_MAP_BG), 0);
    lv_obj_set_style_bg_opa(s.holder, LV_OPA_COVER, 0);
    lv_obj_remove_flag(s.holder, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_remove_flag(s.holder, LV_OBJ_FLAG_OVERFLOW_VISIBLE);

    /* 红框 = 视口边界（只用于肉眼核对裁切/居中，不是地图的一部分）。 */
    {
        lv_obj_t * frame = lv_obj_create(scr);

        lv_obj_remove_style_all(frame);
        lv_obj_set_size(frame, s.vw + 4, s.vh + 4);
        lv_obj_set_pos(frame, -2, -2);
        lv_obj_set_style_bg_opa(frame, LV_OPA_TRANSP, 0);
        lv_obj_set_style_border_width(frame, 2, 0);
        lv_obj_set_style_border_color(frame, lv_color_hex(LIVE_FRAME_COLOR), 0);
        lv_obj_set_style_border_opa(frame, LV_OPA_70, 0);
        lv_obj_remove_flag(frame, LV_OBJ_FLAG_CLICKABLE);
    }

    /* ── 真 vmap 组件（与板端地图页同一份实现） ───────────────────── */
    s.view = vmap_view_create(s.holder, s.vw, s.vh, VMAP_CANVAS_MARGIN);
    if (s.view == NULL) {
        fprintf(stderr, "vmap: vmap_view_create failed (%dx%d)\n", s.vw, s.vh);
        return;
    }

    vmap_view_bind_arrow_layer(s.view, s.holder);
    vmap_view_set_follow_mode(s.view, true);
    vmap_view_set_font(s.view, sim_font_cjk(15));

    alt_icon_build();
    vmap_view_set_center_icon(s.view, icon_src(s.icon));

    vmap_view_set_view(s.view, s.lon, s.lat, zoom);
    vmap_view_set_scale(s.view, s.scale);
    vmap_view_update_arrow(s.view, s.lon, s.lat, 0.0f);
    vmap_view_render(s.view);

    /* ── 拖动面：透明覆盖层吃指针事件（滚轮/按键走 sim_display 通道） ── */
    s.overlay = lv_obj_create(s.holder);
    lv_obj_remove_style_all(s.overlay);
    lv_obj_set_size(s.overlay, s.vw, s.vh);
    lv_obj_set_pos(s.overlay, 0, 0);
    lv_obj_set_style_bg_opa(s.overlay, LV_OPA_TRANSP, 0);
    lv_obj_add_flag(s.overlay, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_add_event_cb(s.overlay, drag_cb, LV_EVENT_ALL, NULL);

    /* ── HUD ──────────────────────────────────────────────────────── */
    s.hud = lv_obj_create(scr);
    lv_obj_remove_style_all(s.hud);
    lv_obj_set_width(s.hud, s.vw);
    lv_obj_set_height(s.hud, hud_h);
    hud_y = (s.vh + 8 + hud_h <= sh) ? s.vh + 8 : 4;
    lv_obj_set_pos(s.hud, 0, hud_y);
    lv_obj_set_style_bg_color(s.hud, lv_color_hex(0x000000), 0);
    lv_obj_set_style_bg_opa(s.hud, LV_OPA_70, 0);
    lv_obj_set_style_pad_all(s.hud, 3, 0);
    lv_obj_remove_flag(s.hud, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_add_flag(s.hud, LV_OBJ_FLAG_IGNORE_LAYOUT);
    if (!cfg->vmap_hud) {
        lv_obj_add_flag(s.hud, LV_OBJ_FLAG_HIDDEN);
    }

    s.hud_label = lv_label_create(s.hud);
    lv_obj_set_style_text_font(s.hud_label, &lv_font_montserrat_12, 0);
    lv_obj_set_style_text_color(s.hud_label, lv_color_hex(0xF2F5F8), 0);
    lv_obj_set_style_text_line_space(s.hud_label, 1, 0);
    lv_label_set_text(s.hud_label, "vmap real");
    hud_update();

    /* ── 10 ms 泵（与板端 on_render_pump_wrap 同节奏） ────────────── */
    s.timer = lv_timer_create(live_tick, 10, NULL);

    {
        const int tile_size = 256;

        vmap_latlong_to_pixel(s.lat, s.lon, s.zoom, &cx, &cy);
        printf("[vmap] create vp=%dx%d margin=%d canvas=%dx%d z=%d scale=%.2f "
               "center=%.6f,%.6f tile=%d,%d icon=%s\n",
            s.vw, s.vh, (int)vmap_view_get_margin(s.view),
            s.vw + 2 * (int)vmap_view_get_margin(s.view),
            s.vh + 2 * (int)vmap_view_get_margin(s.view),
            s.zoom, s.scale, s.lon, s.lat,
            (int)(cx / tile_size), (int)(cy / tile_size), icon_name(s.icon));
    }
}
"}

