{"command": "cd /tmp && python3 - <<'EOF'
import struct,zlib

def read_png(path):
    d=open(path,'rb').read(); pos=8; w=h=ct=None; idat=b''
    while pos<len(d):
        ln=struct.unpack('>I',d[pos:pos+4])[0]; typ=d[pos+4:pos+8]; data=d[pos+8:pos+8+ln]; pos+=12+ln
        if typ==b'IHDR': w,h,bd,ct=struct.unpack('>IIBB',data[:10])
        elif typ==b'IDAT': idat+=data
    raw=zlib.decompress(idat); bpp=3 if ct==2 else 4; stride=w*bpp
    out=[]; prev=bytearray(stride); p=0
    for y in range(h):
        f=raw[p]; p+=1; line=bytearray(raw[p:p+stride]); p+=stride
        if f==1:
            for i in range(bpp,stride): line[i]=(line[i]+line[i-bpp])&255
        elif f==2:
            for i in range(stride): line[i]=(line[i]+prev[i])&255
        elif f==3:
            for i in range(stride):
                a=line[i-bpp] if i>=bpp else 0
                line[i]=(line[i]+((a+prev[i])>>1))&255
        elif f==4:
            for i in range(stride):
                a=line[i-bpp] if i>=bpp else 0; b=prev[i]; c=prev[i-bpp] if i>=bpp else 0
                pp=a+b-c; pa=abs(pp-a); pb=abs(pp-b); pc=abs(pp-c)
                pr=a if (pa<=pb and pa<=pc) else (b if pb<=pc else c)
                line[i]=(line[i]+pr)&255
        out.append(bytes(line)); prev=line
    return w,h,bpp,out

w,h,bpp,A=read_png('pan_before.png')
w2,h2,bpp2,B=read_png('pan_after.png')
assert (w,h)==(w2,h2)
H=214  # map area only, exclude HUD/frame

def mad(dx, dy=0):
    tot=0; n=0
    for y in range(4, H-4):
        for x in range(4, w-4):
            xx=x+dx; yy=y+dy
            if 0<=xx<w and 0<=yy<h:
                a=A[y]; b=B[yy]
                ia=x*bpp; ib=xx*bpp
                tot += abs(a[ia]-b[ib])+abs(a[ia+1]-b[ib+1])+abs(a[ia+2]-b[ib+2]); n+=1
    return tot/n if n else 1e9

best=min(range(120,241), key=mad)
print('before vs after: best horizontal shift =', best, 'px  (MAD %.2f)'%mad(best))
for dx in (0, 100, 190, 199, 200, 210):
    print('  dx=%4d  MAD=%.2f'%(dx, mad(dx)))
EOF", "description": "Correlate before/after pan screenshots", "timeout": 180000}

